functions.setup_body:
resp = await client.get(BASE + "/sections")
sections = resp.json()
return {
    "sections": [s["section"] for s in sections],
    "start_gap": sum(s["orders"] for s in sections) - sum(s["seats_sold"] for s in sections),
}

functions.request_body:
sections = ctx["sections"]
body = {
    "section": sections[i % len(sections)],
    "buyer_email": "fan" + str(i) + "@example.com",
}
return await client.post(BASE + "/checkout", json=body)
